ApplicationContext ac =
    new AnnotationConfigApplicationContext(AppConfig.class);

// EnvironmentCapable
System.out.println("java = "
    + ac.getEnvironment().getProperty("java.version"));
System.out.println("profiles = "
    + java.util.Arrays.toString(
          ac.getEnvironment().getActiveProfiles()));

// ResourceLoader
System.out.println("resource = "
    + ac.getResource("classpath:application.properties"));

// BeanFactory 로도 쓸 수 있다 — 상속했으니까
BeanFactory bf = ac;
System.out.println("bean = " + bf.getBean("memberService"));
